// verify/gate.test.mjs — verifier-owned gate-semantics tests with a fake clock.
//
// Drives the real `Gate` class from lib/host/gate.js with:
//   * a virtual clock (`vnow`) that only moves when the test says so,
//   * a fake single-shot scheduler so timer arming/firing/leaking is observable,
//   * the REAL schedule core for classify/nextTransition (so 09:00/12:00/14:00/18:00 are real).
// No author test is imported and no expectation is generated by the implementation.
import test from 'node:test'
import assert from 'node:assert/strict'
import { bjEpoch, bjParts } from './lib/oracle.mjs'

let gateMod = null, core = null, loadErr = null
try {
  gateMod = await import('../lib/host/gate.js')
  core = await import('../lib/core/index.js')
} catch (e) { loadErr = e }
const missing = gateMod && core ? false : `lib/host/gate.js or lib/core/index.js unavailable: ${loadErr?.message}`

const WED = [2026, 10, 14]
const at = (h, mi, s = 0) => bjEpoch(WED[0], WED[1], WED[2], h, mi, s)

/** Virtual clock + fake scheduler + gate factory. */
function harness({ mode = 'idle-only', now = at(9, 0), peakLeadMs, ...rest } = {}) {
  const clock = { vnow: now }
  const pending = new Map()
  let seq = 0
  const schedule = (delayMs, cb) => {
    const id = ++seq
    pending.set(id, { at: clock.vnow + delayMs, cb, delayMs })
    return () => { pending.delete(id) }
  }
  const gate = new gateMod.Gate({
    now: () => clock.vnow,
    classify: (t) => core.classify(t),
    nextTransition: (t) => core.nextTransition(t),
    getMode: () => state.mode,
    schedule,
    ...(peakLeadMs === undefined ? {} : { peakLeadMs }),
    ...rest,
  })
  const state = { mode }
  /** Move the virtual clock to `target`, firing every timer due on the way (in order). */
  const advanceTo = (target) => {
    for (;;) {
      let next = null
      for (const [id, t] of pending) if (t.at <= target && (next === null || t.at < pending.get(next).at)) next = id
      if (next === null) break
      const t = pending.get(next)
      pending.delete(next)
      clock.vnow = Math.max(clock.vnow, t.at)
      t.cb()
    }
    clock.vnow = Math.max(clock.vnow, target)
  }
  return { clock, pending, gate, state, advanceTo, scheduledDelays: () => [...pending.values()].map((t) => t.delayMs) }
}

/** Observable settlement state of a promise. */
function tracker(p) {
  const rec = { status: 'pending', value: undefined }
  p.then((v) => { rec.status = 'resolved'; rec.value = v }, (e) => { rec.status = 'rejected'; rec.value = e })
  return rec
}
const flush = async () => { for (let i = 0; i < 10; i++) await Promise.resolve(); await new Promise((r) => setTimeout(r, 0)) }

test('subject module present (lib/host/gate.js)', () => {
  assert.ok(gateMod && core, missing)
})

test('peak: wait() holds, arms exactly one timer at the idle boundary, releases exactly there', { skip: missing }, async () => {
  const h = harness({ now: at(9, 0) })
  const p = tracker(h.gate.wait(new AbortController().signal))
  await flush()
  assert.equal(p.status, 'pending', 'a wait started inside a peak window must not resolve')
  assert.equal(h.gate.waiterCount, 1)
  assert.equal(h.gate.isPaused(), true)
  assert.equal(h.pending.size, 1, 'exactly one timer must be armed')
  assert.equal(h.gate.targetAt, at(12, 0), `timer must target 12:00:00, got ${bjParts(h.gate.targetAt).text}`)

  h.advanceTo(at(11, 59, 59))
  await flush()
  assert.equal(p.status, 'pending', 'must still be held 1 s before the boundary')
  assert.equal(h.pending.size, 1)

  h.advanceTo(at(12, 0))
  await flush()
  assert.equal(p.status, 'resolved', 'must be released exactly at 12:00:00')
  assert.equal(h.gate.waiterCount, 0)
  assert.equal(h.gate.timerArmed, false, 'no timer may survive the release')
  assert.equal(h.pending.size, 0, 'no timer leak after release')
})

test('peak: an afternoon hold targets 18:00 and releases there', { skip: missing }, async () => {
  const h = harness({ now: at(14, 30) })
  const p = tracker(h.gate.wait(new AbortController().signal))
  await flush()
  assert.equal(p.status, 'pending')
  assert.equal(h.gate.targetAt, at(18, 0))
  h.advanceTo(at(18, 0))
  await flush()
  assert.equal(p.status, 'resolved')
  assert.equal(h.pending.size, 0)
})

test('SPEC §3.4 + §2.4: an idle instant never holds — 08:59:00 and 12:00:00 pass straight through', { skip: missing }, async () => {
  for (const t of [at(8, 59), at(12, 0), at(13, 59), at(18, 0), at(23, 0)]) {
    const h = harness({ now: t })
    const p = tracker(h.gate.wait(new AbortController().signal))
    await flush()
    assert.equal(p.status, 'resolved', `${bjParts(t).text} is idle and must not hold`)
    assert.equal(h.gate.waiterCount, 0)
    assert.equal(h.pending.size, 0, 'an idle wait must not arm a timer')
    assert.equal(h.gate.isPaused(), false)
  }
})

// SPEC §3 item 4 was re-ruled by the Lead on 2026-10-09 (default `peakLeadMs = 0`): an idle-phase
// gate check is released immediately and registers no waiter; a peak-phase check is held until the
// exact next idle boundary; and a task released at 08:59:59 is held at its NEXT gate check once
// that check falls at or after 09:00:00.000 — the real "running task auto-pauses at peak" path.
// (This replaced the earlier literal reading "entering the gate at 08:59:59 stays held", which
// needed a lead guard the frozen default does not enable. Finding F4 is now closed by ruling.)
test('SPEC §3.4 running-task path: released at 08:59:59, HELD at the next gate check after 09:00:00', { skip: missing }, async () => {
  const h = harness({ now: at(8, 59, 59) })
  const first = tracker(h.gate.wait(new AbortController().signal))
  await flush()
  assert.equal(first.status, 'resolved', '08:59:59 is idle: the check must not hold')
  assert.equal(h.gate.waiterCount, 0, 'an idle-phase check registers no waiter')
  assert.equal(h.pending.size, 0, 'an idle-phase check must not arm a timer')

  h.advanceTo(at(9, 0, 1))                       // the task's next step, now inside the peak window
  const second = tracker(h.gate.wait(new AbortController().signal))
  await flush()
  assert.equal(second.status, 'pending', 'the next check after 09:00:00 must be held')
  assert.equal(h.gate.waiterCount, 1)
  assert.equal(h.gate.targetAt, at(12, 0))
  h.advanceTo(at(12, 0))
  await flush()
  assert.equal(second.status, 'resolved', 'and released exactly at the idle boundary')
  assert.equal(h.pending.size, 0)
})

test('SPEC §3.4: a peak-phase check is held from 09:00:00.000 and from 17:59:59.999', { skip: missing }, async () => {
  for (const [label, t, boundary] of [
    ['09:00:00.000', at(9, 0, 0), at(12, 0)],
    ['14:00:00.000', at(14, 0, 0), at(18, 0)],
    ['17:59:59.999', at(18, 0, 0) - 1, at(18, 0)],
  ]) {
    const h = harness({ now: t })
    const p = tracker(h.gate.wait(new AbortController().signal))
    await flush()
    assert.equal(p.status, 'pending', `${label} is peak and must be held`)
    assert.equal(h.gate.waiterCount, 1)
    assert.equal(h.gate.targetAt, boundary, `${label} must target the exact idle boundary`)
    h.advanceTo(boundary)
    await flush()
    assert.equal(p.status, 'resolved')
    assert.equal(h.pending.size, 0)
  }
})

test('optional lead guard (peakLeadMs=2000): holds 08:59:59 but never over-holds 08:58:00', { skip: missing }, async () => {
  const held = harness({ now: at(8, 59, 59), peakLeadMs: 2000 })
  const p = tracker(held.gate.wait(new AbortController().signal))
  await flush()
  assert.equal(p.status, 'pending', 'with the lead guard a check 1 s before peak is held')
  assert.equal(held.gate.targetAt, at(9, 0), 'the first timer must aim at the upcoming transition (09:00)')
  held.advanceTo(at(9, 0))
  await flush()
  assert.equal(p.status, 'pending', 'still held once the peak window actually starts')
  assert.equal(held.gate.targetAt, at(12, 0), 're-armed at the idle boundary 12:00 (one timer, re-armed)')
  held.advanceTo(at(12, 0))
  await flush()
  assert.equal(p.status, 'resolved')
  assert.equal(held.pending.size, 0)

  const early = harness({ now: at(8, 58, 0), peakLeadMs: 2000 })
  const q = tracker(early.gate.wait(new AbortController().signal))
  await flush()
  assert.equal(q.status, 'resolved', 'a lead guard of 2 s must not hold a task arriving 60 s early')
  assert.equal(early.pending.size, 0)
})

test('mode always never holds, even inside a peak window', { skip: missing }, async () => {
  for (const mode of ['always']) {
    for (const t of [at(9, 0), at(10, 0), at(16, 30)]) {
      const h = harness({ now: t, mode })
      const p = tracker(h.gate.wait(new AbortController().signal))
      await flush()
      assert.equal(p.status, 'resolved', `${mode} @${bjParts(t).text} must not hold`)
      assert.equal(h.gate.waiterCount, 0)
      assert.equal(h.gate.isPaused(), false)
      assert.equal(h.pending.size, 0, 'no timer may be armed in always mode')
    }
  }
})

test('switching mode to always releases an existing waiter and disarms the timer', { skip: missing }, async () => {
  const h = harness({ now: at(10, 0) })
  const p = tracker(h.gate.wait(new AbortController().signal))
  await flush()
  assert.equal(p.status, 'pending')
  h.state.mode = 'always'
  h.gate.notifyChanged()
  await flush()
  assert.equal(p.status, 'resolved')
  assert.equal(h.gate.waiterCount, 0)
  assert.equal(h.pending.size, 0, 'the boundary timer must be cancelled on release')
})

test('clock override expiry (now jumps to idle) releases waiters', { skip: missing }, async () => {
  const h = harness({ now: at(16, 0) })
  const p = tracker(h.gate.wait(new AbortController().signal))
  await flush()
  assert.equal(p.status, 'pending')
  h.clock.vnow = at(19, 0)          // override cleared: real now is idle
  h.gate.notifyChanged()
  await flush()
  assert.equal(p.status, 'resolved')
  assert.equal(h.pending.size, 0)
})

test('abort during a hold propagates (never swallowed) and cleans up', { skip: missing }, async () => {
  const h = harness({ now: at(10, 0) })
  const ac = new AbortController()
  const p = tracker(h.gate.wait(ac.signal))
  await flush()
  assert.equal(p.status, 'pending')
  assert.equal(h.gate.waiterCount, 1)
  ac.abort()
  await flush()
  assert.equal(p.status, 'rejected', 'an abort must reject the wait')
  assert.equal(p.value?.name, 'AbortError', `expected an AbortError, got ${p.value?.name}: ${p.value?.message}`)
  assert.equal(h.gate.waiterCount, 0)
  assert.equal(h.pending.size, 0, 'abort must not leak the boundary timer')
})

test('abort reason is propagated verbatim when the signal carries one', { skip: missing }, async () => {
  const h = harness({ now: at(10, 0) })
  const ac = new AbortController()
  const reason = new Error('verifier-abort-reason')
  const p = tracker(h.gate.wait(ac.signal))
  await flush()
  ac.abort(reason)
  await flush()
  assert.equal(p.status, 'rejected')
  assert.equal(p.value, reason, 'the signal reason must be rethrown, not replaced')
  assert.equal(h.pending.size, 0)
})

test('an already-aborted signal rejects immediately without arming a timer', { skip: missing }, async () => {
  const h = harness({ now: at(10, 0) })
  const ac = new AbortController()
  ac.abort()
  const p = tracker(h.gate.wait(ac.signal))
  await flush()
  assert.equal(p.status, 'rejected')
  assert.equal(h.gate.waiterCount, 0)
  assert.equal(h.pending.size, 0)
})

test('several waiters share ONE timer and are all released together', { skip: missing }, async () => {
  const h = harness({ now: at(10, 0) })
  const acs = [new AbortController(), new AbortController(), new AbortController()]
  const ps = acs.map((ac) => tracker(h.gate.wait(ac.signal)))
  await flush()
  assert.deepEqual(ps.map((p) => p.status), ['pending', 'pending', 'pending'])
  assert.equal(h.gate.waiterCount, 3)
  assert.equal(h.pending.size, 1, 'three waiters must share exactly one boundary timer')
  h.advanceTo(at(12, 0))
  await flush()
  assert.deepEqual(ps.map((p) => p.status), ['resolved', 'resolved', 'resolved'])
  assert.equal(h.gate.waiterCount, 0)
  assert.equal(h.pending.size, 0)
})

test('release is one-shot-safe: aborting after release is a no-op', { skip: missing }, async () => {
  const h = harness({ now: at(10, 0) })
  const ac = new AbortController()
  const p = tracker(h.gate.wait(ac.signal))
  await flush()
  h.advanceTo(at(12, 0))
  await flush()
  assert.equal(p.status, 'resolved')
  ac.abort()                       // listener must already be detached
  await flush()
  assert.equal(p.status, 'resolved', 'the waiter must not change state after release')
  assert.equal(h.gate.waiterCount, 0)
  assert.equal(h.pending.size, 0)
})

test('dispose() releases every waiter and leaves no timer behind', { skip: missing }, async () => {
  const h = harness({ now: at(10, 0) })
  const ps = [tracker(h.gate.wait(new AbortController().signal)), tracker(h.gate.wait(new AbortController().signal))]
  await flush()
  assert.equal(h.pending.size, 1)
  h.gate.dispose()
  await flush()
  assert.deepEqual(ps.map((p) => p.status), ['resolved', 'resolved'], 'held turns must resume on unload, not hang')
  assert.equal(h.gate.waiterCount, 0)
  assert.equal(h.gate.timerArmed, false, 'dispose must disarm the boundary timer')
  assert.equal(h.pending.size, 0, 'dispose must leave no timer behind (SPEC §3.6)')
  // after dispose the gate is inert
  const ac = new AbortController()
  const p3 = tracker(h.gate.wait(ac.signal))
  await flush()
  assert.equal(p3.status, 'resolved')
  assert.equal(h.pending.size, 0)
})

test('never re-arms faster than 1 Hz, even with a degenerate schedule', { skip: missing }, async () => {
  // A nextTransition that never moves would spin a naive implementation.
  const clock = { vnow: at(10, 0) }
  const pending = new Map()
  let seq = 0
  const gate = new gateMod.Gate({
    now: () => clock.vnow,
    classify: () => ({ phase: 'peak' }),
    nextTransition: () => ({ at: clock.vnow, to: 'idle' }),   // stalled: same instant forever
    getMode: () => 'idle-only',
    schedule: (delayMs, cb) => { const id = ++seq; pending.set(id, { delayMs, cb }); return () => pending.delete(id) },
  })
  const p = tracker(gate.wait(new AbortController().signal))
  await flush()
  assert.equal(p.status, 'pending')
  assert.equal(pending.size, 1)
  const delay = [...pending.values()][0].delayMs
  assert.ok(delay >= 1000, `re-arm delay must be >= 1000 ms (1 Hz floor), got ${delay}`)
  gate.dispose()
  await flush()
  assert.equal(pending.size, 0)
})

test('a throwing classify/nextTransition must not hold or throw into the turn', { skip: missing }, async () => {
  const gate = new gateMod.Gate({
    now: () => at(10, 0),
    classify: () => { throw new Error('boom-classify') },
    nextTransition: () => { throw new Error('boom-transition') },
    getMode: () => 'idle-only',
    schedule: () => () => {},
  })
  const p = tracker(gate.wait(new AbortController().signal))
  await flush()
  assert.equal(p.status, 'resolved', 'a broken core must fail open (never hold a turn)')
  gate.dispose()
})

test('missing signal: the gate must not be asked to hold uninterruptibly', { skip: missing }, async () => {
  // lib/host/index.js only calls the gate when isUsableSignal(signal) is true; this pins the
  // class-level behaviour so the wiring assumption stays honest.
  const h = harness({ now: at(10, 0) })
  const p = tracker(h.gate.wait(undefined))
  await flush()
  assert.equal(p.status, 'pending', 'Gate.wait(undefined) holds without an abort path')
  assert.equal(h.gate.waiterCount, 1)
  h.gate.dispose()
  await flush()
  assert.equal(p.status, 'resolved')
})

test('isUsableSignal accepts a real AbortSignal and rejects unusable candidates', { skip: missing }, async () => {
  const { isUsableSignal } = await import('../lib/host/index.js').catch(() => ({}))
  if (typeof isUsableSignal !== 'function') return   // importing index.js may need a ctx; skip silently
  assert.equal(isUsableSignal(new AbortController().signal), true)
  for (const bad of [undefined, null, {}, { aborted: true }, () => {}]) {
    assert.equal(isUsableSignal(bad), false, `isUsableSignal(${JSON.stringify(bad)}) must be false`)
  }
})
